olid var(--el-color-primary)}.principle-block p{margin:3px 0}.formula-box{font-family:"JetBrains Mono",monospace;font-size:12px;padding:8px 12px;border-radius:8px;background:rgba(var(--el-color-primary-rgb,64,158,255),.05);margin:6px 0;font-weight:600}.ref-section{margin-top:16px;padding-top:12px;border-top:1px dashed var(--el-border-color-lighter)}.ref-title{font-size:12px;font-weight:700;margin-bottom:8px;padding-left:8px;border-left:3px solid var(--el-color-warning)}.ref-item{font-size:11px;line-height:1.6;color:var(--el-text-color-secondary);margin:2px 0}.result-fade-enter-active{transition:all .5s cubic-bezier(.16,1,.3,1)}.result-fade-leave-active{transition:all .3s ease}.result-fade-enter-from{opacity:0;transform:translateY(24px)}.result-fade-leave-to{opacity:0;transform:translateY(-12px)}.result-section{animation:slideUp .5s cubic-bezier(.16,1,.3,1)}@keyframes slideUp{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}.metrics-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:14px}.metric-card{position:relative;text-align:center;padding:18px 14px 16px;border-radius:12px;background:var(--el-bg-color);border:1px solid var(--el-border-color-lighter);overflow:hidden;transition:transform .2s,box-shadow .2s}.metric-card:hover{transform:translateY(-2px);box-shadow:0 6px 16px rgba(0,0,0,.06)}.metric-indicator{position:absolute;top:0;left:0;right:0;height:3px}.metric-card.accent .metric-indicator{background:linear-gradient(90deg,#409eff,#66b1ff)}.metric-card.success .metric-indicator{background:linear-gradient(90deg,#67c23a,#85ce61)}.metric-card.warning .metric-indicator{background:linear-gradient(90deg,#e6a23c,#ebb563)}.metric-card.neutral .metric-indicator{background:linear-gradient(90deg,#909399,#a6a9ad)}.metric-label{font-size:12px;color:var(--el-text-color-secondary);margin-bottom:6px}.metric-value{font-size:20px;font-weight:700;font-family:"JetBrains Mono",monospace;line-height:1.2}.card-header-inner{dis